/* From Uiverse.io by ercnersoy - Tags: button */
.__UIV_SCOPE__ button {
  background: #ce1d1d;
  padding: 10px 50px 10px 30px;
  color: white;
  font-family: Verdana, Geneva, Tahoma, sans-serif;
  font-size: 20px;
  border-radius: 80px;
  text-transform: uppercase;
  transition: all .5s ease-in-out;
  border: none;
}

.__UIV_SCOPE__ button:hover:before {
  width: 79px;
  height: 79px;
  transform: translate(4.6pc, -1.8pc);
  background-image: url("data:image/svg+xml;base64,");
}

.__UIV_SCOPE__ button::before {
  content: "";
  background-image: url("data:image/svg+xml;base64,");
  height: 20px;
  width: 20px;
  position: absolute;
  transition: all .5s ease-in-out;
  background-size: 100%;
  transform: translate(6.3pc, 0.2pc);
}
